export function attachmentItems(result){if(result.exceededTransferLimit||!Array.isArray(result.attachmentInfos))throw Error('The service did not return a complete attachment list.');return result.attachmentInfos.map(a=>{if(!Number.isSafeInteger(a.id)||a.id<0)throw Error('Invalid attachment identifier.');return {id:a.id,name:String(a.name||'Attachment '+a.id),type:String(a.contentType||'application/octet-stream').toLowerCase(),size:Number(a.size)||0};});}
export const previewImage=type=>/^image\/(jpeg|png|gif|webp|bmp)$/.test(type);
export async function attachmentBlob(api,url,oid,item,signal){if(!Number.isSafeInteger(oid)||oid<0||!Number.isSafeInteger(item.id)||item.id<0)throw Error('Invalid attachment identifier.');const u=new URL(url);if(u.protocol!=='https:'||u.search||u.hash||u.username||u.password||!api.allowed.has(u.origin))throw Error('Attachment service origin has not been approved.');if(Date.now()>=api.expires)throw Error('Session expired. Sign in again.');u.pathname+='/'+oid+'/attachments/'+item.id;const root=url.replace(/\/\d+$/,'');const version=api.versions.get(root);if(version)u.searchParams.set('gdbVersion',version);const response=await api.fetcher(u.href,{headers:{'X-Esri-Authorization':'Bearer '+api.token},credentials:'omit',cache:'no-store',referrerPolicy:'origin',redirect:'error',signal});if(!response.ok)throw Error('Attachment could not be loaded ('+response.status+').');const type=(response.headers.get('content-type')||'').split(';')[0].toLowerCase();if(type==='application/json'){const data=await response.json();if(data.error)throw Error('ArcGIS '+data.error.code+': '+data.error.message);throw Error('The service returned attachment metadata instead of a file.');}if(type==='text/html'&&item.type!=='text/html')throw Error('The attachment service returned a sign-in page. Sign in again.');if(Number(response.headers.get('content-length'))>30*1024*1024)throw Error('Attachment exceeds the 30 MB viewer limit.');const blob=await response.blob();if(blob.size>30*1024*1024)throw Error('Attachment exceeds the 30 MB viewer limit.');if(previewImage(item.type)&&!previewImage(type))throw Error('The response was not a supported image.');return blob;}
export function attachAlertAttachments({$,auth,isCurrent}){let serial=0,urls=[],controller=null,api=null;function clear(){serial++;controller?.abort();controller=null;for(const url of urls)URL.revokeObjectURL(url);urls=[];api=null;$('monitor-attachments').replaceChildren();$('monitor-attachments-status').textContent='';}
 async function show(issue,meta){clear();const version=serial;const valid=()=>{try{return version===serial&&isCurrent(issue)&&auth()===api;}catch{return false;}};try{api=auth();if(meta?.hasAttachments===false){$('monitor-attachments-status').textContent='This layer does not support attachments.';return;}if(!meta)throw Error('Reload the monitoring layer to view attachments.');controller=new AbortController();$('monitor-attachments-status').textContent='Loading this feature’s photos and attachments…';const gid=meta.fields.find(f=>f.name===issue.globalIdField);if(!gid||!issue.globalId)throw Error('A Global ID is required to verify this feature’s attachments.');const found=await api.request(issue.url+'/query',{objectIds:issue.objectId,outFields:[meta.objectIdField,gid.name].join(','),returnGeometry:false});if(!valid())return;const feature=found.features?.find(f=>f.attributes[meta.objectIdField]===issue.objectId);if(!feature||String(feature.attributes[gid.name]).replace(/[{}]/g,'').toLowerCase()!==String(issue.globalId).replace(/[{}]/g,'').toLowerCase())throw Error('This feature no longer matches the alert Global ID. Run a fresh check.');const params={};const v=api.versions.get(issue.url.replace(/\/\d+$/,''));if(v)params.gdbVersion=v;const result=await api.request(issue.url+'/'+issue.objectId+'/attachments',params);if(!valid())return;const items=attachmentItems(result);$('monitor-attachments-status').textContent=items.length?items.length+' attachment(s). Photos load here; other files can be downloaded.':'No attachments are linked to this feature.';let auto=0;for(const item of items){const card=document.createElement('section');card.className='attachment-card';const title=document.createElement('p'),button=document.createElement('button'),note=document.createElement('p'),content=document.createElement('div');title.textContent=item.name+' · '+item.type+(item.size?' · '+(item.size/1024).toFixed(0)+' KB':'');button.type='button';button.textContent=previewImage(item.type)?'View photo':'Download attachment';card.append(title,button,note,content);$('monitor-attachments').append(card);async function load(){button.disabled=true;note.textContent='Loading…';try{if(!valid())return;const blob=await attachmentBlob(api,issue.url,issue.objectId,item,controller.signal);if(!valid())return;const url=URL.createObjectURL(blob);urls.push(url);if(previewImage(item.type)){const image=document.createElement('img'),link=document.createElement('a');image.src=url;image.alt=item.name;image.onerror=()=>{note.textContent='This image format could not be displayed.';};link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Open full-size photo';content.replaceChildren(image,link);button.hidden=true;note.textContent='';}else{const link=document.createElement('a');link.href=url;link.download=item.name;document.body.append(link);link.click();link.remove();note.textContent='Download prepared.';}}catch(error){if(valid())note.textContent=error.message;}finally{button.disabled=false;}}button.onclick=load;if(previewImage(item.type)&&item.size<=10*1024*1024&&auto++<3)load();}}catch(error){if(version===serial&&isCurrent(issue))$('monitor-attachments-status').textContent='Attachments unavailable: '+error.message;}}
 $('monitor-issue-dialog').addEventListener('close',clear);window.addEventListener('pagehide',clear);return {show,clear,checkSession(){if(api){try{if(auth()!==api)clear();}catch{clear();}}}};
}
